sc_cat_item_producer.script:
(function() {
    new x_hccc_hoc_ohs.HoCOHSRecordProducerUtil().createCaseFromProducer(current, producer, cat_item.sys_id); //TODO: IS THIS REQUIRED? RISK FOR ANONYMOUS FEATURE?
    producer.portal_redirect = "?id=hoc_ohsm_confirmation&hrService=hv";
    current.state = 109; //Initial Review
    current.complainant_feels_in_imminent_danger = producer.feel_in_imminent_danger;

    current.submitted_by_the_subject_of_harassement = producer.are_you_filing_this_complaint_on_your_own_behalf == "yes" ? "yes" : "no";
    current.hv_remain_anonymous = producer.hv_remain_anonymous == "yes" ? "yes" : "no";

    var language = gs.getSession().getLanguage();
    current.short_description = (language == "fq") ? "Cas de plainte pour harcèlement ou violence" : "Harassment and Violence Complaint case";

    //Generate the description
    var rich_description = "";
    var occurences_list = JSON.parse(producer.harassement_and_violence_occurences);

    for (var i = 0; i < occurences_list.length; i++) {
        var field = "";
        var value = "";

        rich_description += "<p class=\"descriptionFormatted\"><span style=\"text-decoration: underline;\"><strong><span style=\"font-size: 10pt;\">Occurrence #" + (i + 1) + "</span></strong></span></p>";

        field = (language == "fq") ? "Détails de l'incident" : "Detail(s) of the occurrence";
        value = occurences_list[i].details_of_the_occurence;
        rich_description += "<p class=\"descriptionFormatted\">" + field + "<br /><strong>" + value + "</strong></p>";

        field = (language == "fq") ? "Personnes en cause et description de l'implication" : "Individuals Involved in the occurrence & Description of involvement";
        value = occurences_list[i].individuals_involved_and_description;
        rich_description += "<p class=\"descriptionFormatted\">" + field + "<br /><strong>" + value + "</strong></p>";

        field = (language == "fq") ? "Témoin(s) de l'événement" : "Witness(s) of the occurrence";
        value = (occurences_list[i].witnesses_of_the_occurence == undefined) ? "N/A" : occurences_list[i].witnesses_of_the_occurence;
        rich_description += "<p class=\"descriptionFormatted\">" + field + "<br /><strong>" + value + "</strong></p>";

        field = (language == "fq") ? "Date et heure de l'incident?" : "Date and time of incident?";
        value = occurences_list[i].date_and_time_of_occurence;
        rich_description += "<p class=\"descriptionFormatted\">" + field + "<br /><strong>" + value + "</strong></p>";

        field = (language == "fq") ? "Autres renseignements que vous jugez pertinents" : "Other information that you believe is relevant";
        value = (occurences_list[i].other_relevant_information == undefined) ? "N/A" : occurences_list[i].other_relevant_information;
        rich_description += "<p class=\"descriptionFormatted\">" + field + "<br /><strong>" + value + "</strong></p>";

        field = (language == "fq") ? "Type d'interaction" : "Type of interaction";
        value = occurences_list[i].location_type;


        var locationValues = ['email', 'in person', 'text_message', 'phone_call', 'ms_teams', 'social_media', 'other'];
        var locationValuesEn = ['Email', 'In person', 'Text message', 'Phone call', 'MS Teams', 'Social Media', 'Other'];
        var locationValuesFq = ['Courriel', 'En personne', 'Message texte', 'Appel téléphonique', 'MS Teams', 'Média sociaux', 'Autre'];

        if (locationValues.indexOf(value) > -1) {
            if (language == 'fq') {
                value = locationValuesFq[locationValues.indexOf(value)];
            } else {
                value = locationValuesEn[locationValues.indexOf(value)];
            }
        }
        rich_description += "<p class=\"descriptionFormatted\">" + field + "<br /><strong>" + value + "</strong></p>";


        var locationQuery = new x_hccc_hoc_ohs.HoCOHSMQuery();

        field = (language == "fq") ? "Édifice" : "Building";
        value = (occurences_list[i].location_building == undefined) ? "N/A" : locationQuery.getLocationName(occurences_list[i].location_building);
        rich_description += "<p class=\"descriptionFormatted\">" + field + "<br /><strong>" + value + "</strong></p>";

        field = (language == "fq") ? "Salle" : "Room";
        value = (occurences_list[i].room == undefined) ? "N/A" : locationQuery.getLocationName(occurences_list[i].room);
        rich_description += "<p class=\"descriptionFormatted\">" + field + "<br /><strong>" + value + "</strong></p>";

        field = (language == "fq") ? "Détails de l'emplacement" : "Location details";
        value = (occurences_list[i].location_details == undefined) ? "N/A" : occurences_list[i].location_details;
        rich_description += "<p class=\"descriptionFormatted\">" + field + "<br /><strong>" + value + "</strong></p>";

    }
    current.rich_description = rich_description;


    //Submitter information
    current.hv_witness_name = producer.submitter_name;

    var submitter_details = '';
    var submitter_field = '';

    if (!producer.submitter_phone_number.nil()) {
        submitter_field = (language === "fq") ? "Numéro de téléphone du demandeur" : "Submitter phone number";
        submitter_details = "<p class=\"descriptionFormatted\">" + submitter_field + "<br /><strong>" + producer.submitter_phone_number + "</strong></p>";
    }

    if (!producer.submitter_email_address.nil()) {
        submitter_field = (language === "fq") ? "Adresse courriel du demandeur" : "Submitter email address";
        submitter_details += "<p class=\"descriptionFormatted\">" + submitter_field + "<br /><strong>" + producer.submitter_email_address + "</strong></p>";
    }

    current.submitter_contact_details = submitter_details;

    //Complainant information ()
    current.complainant_name = producer.complainant_name;
    current.hv_complainant_manager = producer.complainant_manager;

    var complainant_contact_details = "";
    var complainant_value = "";
    var complainant_field = "";

    complainant_value = producer.complainant_phone_number;
    if (!complainant_value.nil()) {
        complainant_field = (language === "fq") ? "Numéro de téléphone de la partie principale" : "Princial party's phone number";
        complainant_contact_details += "<p class=\"descriptionFormatted\">" + complainant_field + "<br /><strong>" + complainant_value + "</strong></p>";
    }

    complainant_value = producer.complainant_email_address;
    if (!complainant_value.nil()) {
        complainant_field = (language === "fq") ? "Adresse courriel de la partie principale" : "Principal party's email address";
        complainant_contact_details += "<p class=\"descriptionFormatted\">" + complainant_field + "<br /><strong>" + complainant_value + "</strong></p>";
    }


    complainant_value = producer.complainant_description;
    if (!complainant_value.nil()) {
        complainant_field = (language === "fq") ? "Description du partie principale" : "Principal party's description";
        complainant_contact_details += "<p class=\"descriptionFormatted\">" + complainant_field + "<br /><strong>" + complainant_value + "</strong></p>";
    }

    current.complainant_contact_details = complainant_contact_details;

    //Respondent information 
    var respondent_list = "";


    var hv_list_of_respondents = JSON.parse(producer.list_of_respondents);


    for (var j = 0; j < hv_list_of_respondents.length; j++) {
        var respondent_header = "";
        var respondent_field = "";
        var respondent_value = "";

        respondent_header = (language === "fq") ? "Intimé #" : "Respondent #";


        respondent_list += "<p class=\"descriptionFormatted\"><span style=\"text-decoration: underline;\"><strong><span style=\"font-size: 10pt;\">" + respondent_header + (j + 1) + "</span></strong></span></p>";

        if (hv_list_of_respondents[j].do_you_know_the_identity_of_the_defendent === "yes") {

            respondent_value = hv_list_of_respondents[j].defendant_name;
            if (respondent_value) {
                respondent_field = (language === "fq") ? "Nom de l'intimé" : "Respondent name";
                respondent_list += "<p class=\"descriptionFormatted\">" + respondent_field + "<br /><strong>" + respondent_value + "</strong></p>";
            }

            respondent_value = hv_list_of_respondents[j].defendant_manager;
            if (respondent_value) {
                respondent_field = (language === "fq") ? "Gestionnaire ou employeur de l'intimé" : "Respondent manager or employer";
                respondent_list += "<p class=\"descriptionFormatted\">" + respondent_field + "<br /><strong>" + respondent_value + "</strong></p>";
            }

            respondent_value = hv_list_of_respondents[j].defendant_phone_number;
            if (respondent_value) {
                respondent_field = (language === "fq") ? "Numéro de téléphone de l'intimé" : "Respondent phone number";
                respondent_list += "<p class=\"descriptionFormatted\">" + respondent_field + "<br /><strong>" + respondent_value + "</strong></p>";
            }

            respondent_value = hv_list_of_respondents[j].defendant_email_address;
            if (respondent_value) {
                respondent_field = (language === "fq") ? "Adresse courriel de l'intimé" : "Respondent email address";
                respondent_list += "<p class=\"descriptionFormatted\">" + respondent_field + "<br /><strong>" + respondent_value + "</strong></p>";
            }

        } else {
            respondent_field = (language === "fq") ? "Description de l'intimé" : "Respondent description";
            respondent_value = hv_list_of_respondents[j].respondent_description;
            respondent_list += "<p class=\"descriptionFormatted\">" + respondent_field + "<br /><strong>" + respondent_value + "</strong></p>";
        }
    }
    current.respondent_list = respondent_list;

    //Results of the occurences
    current.hv_resulted_in_an_injury = producer.hv_resulted_in_an_injury == "true" ? "yes" : "no";
    current.hv_resulted_in_time_loss = producer.hv_resulted_in_time_loss == "true" ? "yes" : "no";
    current.hv_resulted_in_modified_duties = producer.hv_resulted_in_modified_duties == "true" ? "yes" : "no";

    //If the manager is selected, he will be the person handling the case automatically.
    current.recipient_of_this_complaint = producer.handled_by_complainant_manager == "true" ? "manager" : "designated_recipient";
    current.manager_involved = producer.handled_by_complainant_manager == "true" ? "yes" : "no";

    if (producer.handled_by_complainant_manager == "true" && producer.complainant_manager) {
        current.assigned_to = producer.complainant_manager;
        current.assignment_group = "";
    } else {
        current.assignment_group = "b4a1b2c2db927c109b09e6fa4b961983"; //CEH-HRS-OHS-Respectful Workplace group
        current.assigned_to = "";
    }

    if (current.hv_remain_anonymous == "yes") {
        //ANONYMOUS SUBMISSION
        var producer_copy = {
            number: "",
            feel_in_imminent_danger: "",
            are_you_filing_this_complaint_on_your_own_behalf: "",
            hv_remain_anonymous: "",
            short_description: "",
            rich_description: "",

            assigned_to: "",
            assignment_group: "",

            complainant_name: "",
            complainant_manager: "",
            complainant_contact_details: "",
            respondent_list: "",

            hv_resulted_in_an_injury: "",
            hv_resulted_in_time_loss: "",
            hv_resulted_in_modified_duties: "",
            recipient_of_this_complaint: "",
            manager_involved: ""
        };

        producer_copy.number = "" + current.number;
        producer_copy.feel_in_imminent_danger = "" + producer.feel_in_imminent_danger;
        producer_copy.are_you_filing_this_complaint_on_your_own_behalf = "" + current.submitted_by_the_subject_of_harassement;
        producer_copy.hv_remain_anonymous = producer.hv_remain_anonymous == "yes" ? "yes" : "no";
        producer_copy.short_description = "" + current.short_description;
        producer_copy.rich_description = "" + current.rich_description;

        producer_copy.assigned_to = "" + current.assigned_to.sys_id.toString(); 
        producer_copy.assignment_group = "" + current.assignment_group;

        producer_copy.complainant_name = "" + producer.complainant_name;
        producer_copy.complainant_manager = "" + producer.complainant_manager;
        producer_copy.complainant_contact_details = "" + current.complainant_contact_details;
        producer_copy.respondent_list = "" + current.respondent_list;

        producer_copy.hv_resulted_in_an_injury = "" + current.hv_resulted_in_an_injury;
        producer_copy.hv_resulted_in_time_loss = "" + current.hv_resulted_in_time_loss;
        producer_copy.hv_resulted_in_modified_duties = "" + current.hv_resulted_in_modified_duties;
        producer_copy.recipient_of_this_complaint = "" + current.recipient_of_this_complaint;
        producer_copy.manager_involved = "" + current.manager_involved;
		//gs.info(JSON.stringify(producer_copy))
        new global.HoCOHSMAnonymousCaseCreation().requestAsyncCreation(JSON.stringify(producer_copy));
		//gs.info('made it past the schedule')
        current.setAbortAction(true);
        //Page redirection
        producer.portal_redirect = "?id=hoc_ohsm_confirmation&hrService=hv" + "&anonymous=true";
    }


})();
